const cfg = $('⚙️ Configurações').first().json;

const fmtPG = (d) => d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0');
const fmtLabel = (d) => String(d.getDate()).padStart(2,'0') + '/' + String(d.getMonth()+1).padStart(2,'0') + '/' + d.getFullYear();
const parseYMD = (str) => {
  const parts = str.split('-').map(Number);
  return new Date(parts[0], parts[1] - 1, parts[2]);
};
const fmtLabelStr = (ymdStr) => {
  const parts = ymdStr.split('-');
  return `${parts[2]}/${parts[1]}/${parts[0]}`;
};

let start_date, end_date, start_date_ant, end_date_ant, dataRef, dataRefAnt;

const hasCustom = cfg.data_inicio_custom && typeof cfg.data_inicio_custom === 'string' && cfg.data_inicio_custom.trim() !== '' &&
                  cfg.data_fim_custom && typeof cfg.data_fim_custom === 'string' && cfg.data_fim_custom.trim() !== '';

if (hasCustom) {
  start_date = cfg.data_inicio_custom.trim();
  end_date = cfg.data_fim_custom.trim();
  const dStart = parseYMD(start_date);
  const dEnd = parseYMD(end_date);
  const diffTime = Math.abs(dEnd - dStart);
  const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)) + 1;
  const shiftDays = diffDays > 0 ? diffDays : 7;

  const dStartAnt = new Date(dStart);
  dStartAnt.setDate(dStart.getDate() - shiftDays);
  const dEndAnt = new Date(dEnd);
  dEndAnt.setDate(dEnd.getDate() - shiftDays);

  start_date_ant = fmtPG(dStartAnt);
  end_date_ant = fmtPG(dEndAnt);
  dataRef = fmtLabelStr(start_date) + ' a ' + fmtLabelStr(end_date);
  dataRefAnt = fmtLabel(dStartAnt) + ' a ' + fmtLabel(dEndAnt);
} else {
  // Regra Oficial: Execução na Terça-feira com Fechamento de Segunda a Segunda
  const agora = new Date();
  const dow = agora.getDay(); // 0=Dom, 1=Seg, 2=Ter, 3=Qua, 4=Qui, 5=Sex, 6=Sab

  // Se rodar na terça (dow=2), a segunda de ontem (fim da semana) = recuo de 1 dia
  const recuoFim = (dow === 1 ? 7 : (dow === 2 ? 1 : (dow === 0 ? 6 : dow - 1)));

  const fim = new Date(agora);
  fim.setDate(agora.getDate() - recuoFim);

  const inicio = new Date(fim);
  inicio.setDate(fim.getDate() - 7);

  const inicioAnt = new Date(inicio);
  inicioAnt.setDate(inicio.getDate() - 7);

  const fimAnt = new Date(inicio);

  start_date = fmtPG(inicio);
  end_date = fmtPG(fim);
  start_date_ant = fmtPG(inicioAnt);
  end_date_ant = fmtPG(fimAnt);
  dataRef = fmtLabel(inicio) + ' a ' + fmtLabel(fim);
  dataRefAnt = fmtLabel(inicioAnt) + ' a ' + fmtLabel(fimAnt);
}

return [{
  json: {
    start_date,
    end_date,
    start_date_ant,
    end_date_ant,
    dataRef,
    dataRefAnt,
    modo_producao: cfg.modo_producao,
    email_teste: cfg.email_teste,
    top_postos: cfg.top_postos
  }
}];

// ===========================================================================
// Gerar HTML + CSV — Combustível Semanal por Filial
// v1.1 — cabecalho na identidade TruckPag (icone real do portal deles,
// padrao de linhas topograficas do contrato), corpo em ledger verde,
// RODAPE igual ao da familia Torre de Controle (mesmo padrao do rastreador:
// faixa azul institucional #213035, logo branca Gritsch, mesmo texto).
// Decisao do usuario: so o topo e livre pra usar a marca do parceiro; o
// fechamento do e-mail segue o padrao Gritsch, igual todo relatorio da Torre.
//
// LOGICA DE NEGOCIO PRESERVADA do node original (so a pele mudou):
//   - desvio ANP: pagar ABAIXO da media nacional (ANP) e favoravel (verde)
//
// v1.2 (24/08/2026) -- relatorio virou informativo, nao prescritivo:
//   - removida a coluna "Situacao" (Favoravel/Estavel/Atencao) de toda
//     tabela; ficam so os numeros (atual/anterior/variacao)
//   - Top 5 maiores gastos ganhou coluna de preco medio pago por litro
//   - tabelas que sao um recorte COMPLETO (Combustivel por tipo, Custo por
//     grupo de veiculo) ganharam linha de TOTAL no rodape
//
// O QUE SAIU (foi pro relatorio de pedagio separado):
//   total_gasto_pedagio, custo_km_total (combustivel+pedagio), a tabela de
//   pracas de pedagio, cleanTollName() -- nada disso pertence aqui mais.
// ===========================================================================

const d = $input.item.json;
const cfgNode = $('⚙️ Configurações').first().json;
const perNode = $('Calcular Período').first().json;

const cfg = {
  top_postos: cfgNode.top_postos || 8,
  modo_producao: cfgNode.modo_producao || false,
  email_teste: cfgNode.email_teste || 'gabriel.brittes@gritsch.com.br',
};
const per = { dataRef: perNode.dataRef || 'Semana Atual' };

const emailFinal = cfg.modo_producao ? (d.email_gestor || cfg.email_teste) : cfg.email_teste;

// CC: mesma logica da telemetria (node 14) -- funde email_cc + cc_regional +
// cc_global, deduplica e separa por virgula. Antes o combustivel so usava
// email_cc cru, sem regional nem global -- por isso o padrao de envio
// divergia da telemetria. Corrigido 24/08/2026.
const ccParts = [];
if (d.email_cc) ccParts.push(d.email_cc);
if (d.cc_regional) ccParts.push(d.cc_regional);
if (d.cc_global) ccParts.push(d.cc_global);
const ccMerged = ccParts.join(';').split(/[;,]+/).map(s => s.trim()).filter(Boolean)
  .filter((v, i, a) => a.indexOf(v) === i).join(',');
const ccFinal = cfg.modo_producao ? ccMerged : '';

// --- Paleta TruckPag (v. justificativa no design plan) --------------------
const VERDE       = '#00B140';
const VERDE_ESC   = '#067A34';
const GRAFITE     = '#1D2321';
const CINZA       = '#5B645F';
const LINHA       = '#DCE3DE';
const FUNDO       = '#F4F7F5';
const BRANCO      = '#FFFFFF';
const ALERTA      = '#C23B33';
const ATENCAO     = '#B8791A';

const F_DISPLAY = "'Manrope','Segoe UI',Arial,sans-serif";
const F_CORPO   = "'IBM Plex Sans','Segoe UI',Arial,sans-serif";

// Logo oficial completa (icone + wordmark "truckpag" numa imagem so), vetor
// oficial que o usuario baixou (greenLogo-CXg1UoX3.svg, cor #23D23C). Mais
// confiavel que icone+texto separados, que dependia da fonte Manrope
// carregar no cliente de e-mail. Antes disso, uma URL ao vivo do portal de
// login da TruckPag tambem quebrou no Gmail (24/08/2026) -- por isso a
// decisao de nao depender mais da infraestrutura deles.
// Anexo inline (CID), nao URL externa -- o n8n 2.11.3 (EmailSend v2) da
// cid=nomeDaPropriedadeBinaria a todo item de options.attachments, entao
// basta referenciar cid:logo_truckpag no <img>. Evita de vez o bloqueio
// de data:URI do Gmail e qualquer WAF/hotlink-protection do host externo.
const TRUCKPAG_LOGO_B64 = '';
const GRITSCH_LOGO_BRANCA = 'https://gritsch.com.br/wp-content/uploads/2023/07/logo_branca1080.png';
const AZUL_GRITSCH = '#213035';

// --- Formatadores (identicos ao node original) -----------------------------
const moeda = (val) => {
  const n = parseFloat(val) || 0;
  return 'R$ ' + n.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
};
const numBr = (val, dec = 0) => {
  const n = parseFloat(val) || 0;
  return n.toLocaleString('pt-BR', { minimumFractionDigits: dec, maximumFractionDigits: dec });
};
const fmtDec = (v, dec = 2) => {
  if (v === null || v === undefined || isNaN(parseFloat(v))) return 'N/D';
  return parseFloat(v).toFixed(dec).replace('.', ',');
};
const cleanCityUf = (cidade, uf) => {
  let c = (cidade || 'N/D').trim().replace(/S\?O/gi, 'São').replace(/SAO/gi, 'São').replace(/\?/g, '');
  c = c.toLowerCase().replace(/(?:^|\s|\/)\S/g, a => a.toUpperCase())
    .replace(/Sao /gi, 'São ').replace(/Candoi/gi, 'Candói').replace(/Prudentopolis/gi, 'Prudentópolis')
    .replace(/Corbelia/gi, 'Corbélia').replace(/Mambore/gi, 'Mamborê');
  return c + ' / ' + (uf || 'N/D').toUpperCase();
};

// --- Calculo de variacao -----------------------------------------------
// Sem coluna de "Situacao" (Favoravel/Estavel/Atencao) -- decisao do
// usuario 24/08/2026: o relatorio e informativo, nao prescritivo. Os dois
// calculos viraram um so, ja que nao ha mais distincao de julgamento entre
// "volume" e "eficiencia".
const calcVar = (atual, ant, fmt = moeda) => {
  const vAtu = parseFloat(atual) || 0, vAnt = parseFloat(ant) || 0;
  if (vAnt === 0) return { atualStr: fmt(vAtu), antStr: 'N/D', pctStr: 'N/D' };
  const pct = ((vAtu - vAnt) / vAnt) * 100;
  return { atualStr: fmt(vAtu), antStr: fmt(vAnt), pctStr: (pct > 0 ? '+' : '') + pct.toFixed(1) + '%' };
};

// --- Dados --------------------------------------------------------------
const gastoComb = parseFloat(d.total_gasto_comb || 0);
const gastoCombAnt = parseFloat(d.total_gasto_comb_ant || 0);
const litros = parseFloat(d.total_litros || 0);
const litrosAnt = parseFloat(d.total_litros_ant || 0);
const pm = parseFloat(d.preco_medio_litro || 0);
const pmAnt = parseFloat(d.preco_medio_litro_ant || 0);
const totalKm = parseFloat(d.total_km_calculado || 0);
const totalKmAnt = parseFloat(d.total_km_ant || 0);
const custoKm = parseFloat(d.custo_km_comb_medido || 0);
const custoKmAnt = parseFloat(d.custo_km_ant_medido || 0);

const frota = Array.isArray(d.frota_ativa) ? d.frota_ativa : [];
const postos = Array.isArray(d.postos_utilizados) ? d.postos_utilizados : [];
const resumoCombustivel = Array.isArray(d.resumo_combustivel) ? d.resumo_combustivel : [];
const transacoes = Array.isArray(d.transacoes_detalhe) ? d.transacoes_detalhe : [];

const kpiCustoKm = calcVar(custoKm, custoKmAnt, (v) => 'R$ ' + fmtDec(v, 2) + '/km');
const kpiPreco = calcVar(pm, pmAnt, (v) => 'R$ ' + fmtDec(v, 2) + '/L');
const kpiKm = calcVar(totalKm, totalKmAnt, (v) => numBr(v, 0) + ' km');
const kpiGasto = calcVar(gastoComb, gastoCombAnt, moeda);
const kpiLitros = calcVar(litros, litrosAnt, (v) => numBr(v, 0) + ' L');

// --- Componentes de layout --------------------------------------------------
const linhaKpi = (indicador, kpi) =>
  '<tr>'
  + '<td style="padding:11px 16px;font-size:13px;color:' + GRAFITE + ';font-weight:600;'
  + 'border-bottom:1px solid ' + LINHA + ';font-family:' + F_CORPO + '">' + indicador + '</td>'
  + '<td style="padding:11px 16px;text-align:right;font-size:13px;font-weight:700;color:' + GRAFITE + ';'
  + 'border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums;font-family:' + F_CORPO + '">' + kpi.atualStr + '</td>'
  + '<td style="padding:11px 16px;text-align:right;font-size:13px;color:' + CINZA + ';'
  + 'border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums;font-family:' + F_CORPO + '">' + kpi.antStr + '</td>'
  + '<td style="padding:11px 16px;text-align:right;font-size:13px;color:' + CINZA + ';'
  + 'border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums;font-family:' + F_CORPO + '">' + kpi.pctStr + '</td>'
  + '</tr>';

const th = (txt, align) =>
  '<th style="padding:10px 16px;text-align:' + (align || 'left') + ';font-size:11px;font-weight:700;'
  + 'text-transform:uppercase;letter-spacing:0.04em;color:' + BRANCO + ';background:' + VERDE + ';'
  + 'font-family:' + F_CORPO + '">' + txt + '</th>';

const faixaSecao = (titulo) =>
  '<tr><td style="padding:26px 32px 0"><table width="100%" cellpadding="0" cellspacing="0"><tr>'
  + '<td style="background:' + VERDE_ESC + ';border-radius:6px 6px 0 0;padding:10px 18px;'
  + 'font-size:13px;font-weight:700;color:' + BRANCO + ';text-transform:uppercase;letter-spacing:0.03em;'
  + 'font-family:' + F_CORPO + '">' + titulo + '</td></tr></table></td></tr>';

// Linha de TOTAL: pedido do usuario 24/08/2026 -- "sempre ter uma soma no
// final", mesmo repetindo numeros que ja aparecem em cima, pra leitura
// ficar mais facil sem precisar somar na mao. So entra em tabelas que sao
// um recorte COMPLETO (toda unidade cai em algum grupo) -- Top 5/Top N de
// postos sao recorte PARCIAL, uma soma ali enganaria (pareceria o total).
const linhaTotal = (celulas) =>
  '<tr>' + celulas.map((c, i) =>
    '<td style="padding:10px 16px;text-align:' + (i === 0 ? 'left' : 'right') + ';font-weight:800;'
    + 'color:' + GRAFITE + ';font-size:12px;background:' + FUNDO + ';border-top:1.6px solid ' + VERDE + ';'
    + 'font-variant-numeric:tabular-nums;font-family:' + F_CORPO + '">' + c + '</td>'
  ).join('') + '</tr>';

let rowsCombustivel = '';
for (const cbt of resumoCombustivel) {
  rowsCombustivel += '<tr>'
    + '<td style="padding:9px 16px;font-weight:700;color:' + GRAFITE + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-family:' + F_CORPO + '">' + (cbt.grupo_combustivel || 'Combustível') + '</td>'
    + '<td style="padding:9px 16px;text-align:right;color:' + CINZA + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + numBr(cbt.total_litros, 0) + ' L</td>'
    + '<td style="padding:9px 16px;text-align:right;font-weight:700;color:' + GRAFITE + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + moeda(cbt.total_gasto) + '</td>'
    + '<td style="padding:9px 16px;text-align:right;color:' + CINZA + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + moeda(cbt.preco_medio) + '/L</td>'
    + '<td style="padding:9px 16px;text-align:right;color:' + CINZA + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + numBr(cbt.total_km, 0) + ' km</td>'
    + '<td style="padding:9px 16px;text-align:right;font-weight:700;color:' + (cbt.custo_km ? VERDE_ESC : CINZA) + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + (cbt.custo_km ? 'R$ ' + fmtDec(cbt.custo_km, 2) + '/km' : 'N/D') + '</td>'
    + '</tr>';
}
if (resumoCombustivel.length > 0) {
  rowsCombustivel += linhaTotal([
    'TOTAL', numBr(litros, 0) + ' L', moeda(gastoComb), moeda(pm) + '/L',
    numBr(totalKm, 0) + ' km', custoKm ? 'R$ ' + fmtDec(custoKm, 2) + '/km' : 'N/D',
  ]);
}

// --- Top 5 maiores gastos (pedido do usuario 24/08/2026) -------------------
// Ate agora esse ranking so existia dentro do CSV Frota.csv -- o gestor
// tinha que abrir o anexo pra achar o veiculo que mais gastou. Agora entra
// direto no corpo do e-mail, logo depois da tabela comparativa.
const frotaOrdenada = frota.slice().sort((a, b) => (b.valor_total || 0) - (a.valor_total || 0));
const topGastos = frotaOrdenada.slice(0, 5);
let rowsTopGastos = '';
for (const v of topGastos) {
  const litrosV = parseFloat(v.total_litros || 0);
  const precoMedioV = litrosV > 0 ? (parseFloat(v.valor_total || 0) / litrosV) : null;
  rowsTopGastos += '<tr>'
    + '<td style="padding:9px 16px;font-weight:700;color:' + GRAFITE + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-family:' + F_CORPO + '">' + v.placa + '</td>'
    + '<td style="padding:9px 16px;color:' + CINZA + ';font-size:12px;border-bottom:1px solid ' + LINHA + '">' + (v.grupo_veiculo || 'N/D') + '</td>'
    + '<td style="padding:9px 16px;color:' + CINZA + ';font-size:12px;border-bottom:1px solid ' + LINHA + '">' + (v.combustivel || 'N/D') + '</td>'
    + '<td style="padding:9px 16px;text-align:right;color:' + CINZA + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + numBr(v.total_litros, 0) + ' L</td>'
    + '<td style="padding:9px 16px;text-align:right;font-weight:700;color:' + GRAFITE + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + moeda(v.valor_total) + '</td>'
    + '<td style="padding:9px 16px;text-align:right;color:' + CINZA + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + (precoMedioV != null ? moeda(precoMedioV) + '/L' : 'N/D') + '</td>'
    + '<td style="padding:9px 16px;text-align:right;color:' + CINZA + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + (v.custo_km != null ? 'R$ ' + fmtDec(v.custo_km, 2) + '/km' : 'N/D') + '</td>'
    + '</tr>';
}

// --- Custo por grupo de veiculo: media desta filial vs media da FROTA
// TODA no mesmo periodo (pedido do usuario 24/08/2026). Sem coluna de
// Situacao (24/08/2026, informativo) -- so os dois numeros lado a lado,
// pro leitor comparar direto.
const gruposVeiculo = Array.isArray(d.grupos_veiculo) ? d.grupos_veiculo : [];
let rowsGrupoVeiculo = '';
for (const g of gruposVeiculo) {
  const cf = parseFloat(g.custo_km_filial || 0);
  const cr = parseFloat(g.custo_km_referencia || 0);
  rowsGrupoVeiculo += '<tr>'
    + '<td style="padding:9px 16px;font-weight:700;color:' + GRAFITE + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-family:' + F_CORPO + '">' + (g.grupo_veiculo || 'N/D') + '</td>'
    + '<td style="padding:9px 16px;text-align:center;color:' + CINZA + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + (g.qtd_veiculos || 0) + '</td>'
    + '<td style="padding:9px 16px;text-align:right;color:' + CINZA + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + moeda(g.gasto_grupo) + '</td>'
    + '<td style="padding:9px 16px;text-align:right;font-weight:700;color:' + GRAFITE + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + (cf ? 'R$ ' + fmtDec(cf, 2) + '/km' : 'N/D') + '</td>'
    + '<td style="padding:9px 16px;text-align:right;color:' + CINZA + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + (cr ? 'R$ ' + fmtDec(cr, 2) + '/km' : 'N/D') + '</td>'
    + '</tr>';
}
if (gruposVeiculo.length > 0) {
  rowsGrupoVeiculo += linhaTotal([
    'TOTAL', String(gruposVeiculo.reduce((s, g) => s + (g.qtd_veiculos || 0), 0)),
    moeda(gastoComb), custoKm ? 'R$ ' + fmtDec(custoKm, 2) + '/km' : 'N/D', '—',
  ]);
}

const postosOrdenados = postos.slice().sort((a, b) => (b.total_litros || 0) - (a.total_litros || 0));
let rowsPostos = '';
for (const p of postosOrdenados) {
  const desvio = parseFloat(p.desvio_anp || 0);
  const desvioStr = (desvio > 0 ? '+' : '') + fmtDec(desvio, 1) + '%';
  const desvioCor = desvio <= 0 ? VERDE_ESC : ALERTA;
  rowsPostos += '<tr>'
    + '<td style="padding:9px 16px;font-weight:700;color:' + GRAFITE + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-family:' + F_CORPO + '">' + (p.posto || 'Posto') + '</td>'
    + '<td style="padding:9px 16px;color:' + CINZA + ';font-size:12px;border-bottom:1px solid ' + LINHA + '">' + cleanCityUf(p.cidade, p.uf) + '</td>'
    + '<td style="padding:9px 16px;color:' + CINZA + ';font-size:12px;border-bottom:1px solid ' + LINHA + '">' + (p.combustivel || 'N/D') + '</td>'
    + '<td style="padding:9px 16px;text-align:right;color:' + CINZA + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + numBr(p.total_litros, 0) + ' L</td>'
    + '<td style="padding:9px 16px;text-align:right;font-weight:700;color:' + GRAFITE + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + moeda(p.total_gasto) + '</td>'
    + '<td style="padding:9px 16px;text-align:right;color:' + GRAFITE + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + moeda(p.preco_medio) + '/L</td>'
    + '<td style="padding:9px 16px;text-align:center;font-weight:700;color:' + desvioCor + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + desvioStr + '</td>'
    + '</tr>';
}

// Tarja visual de teste removida a pedido do usuario (24/08/2026) -- o e-mail
// deve ficar visualmente identico ao que vai pra producao. O modo_producao
// continua controlando SO o destinatario (emailFinal/ccFinal acima), nao
// mais a aparencia do corpo do e-mail.
const faixaTeste = '';

// Faixa de contorno topografico -- o detalhe do CONTRATO da TruckPag (linhas
// de "curva de nivel" emolduram cada pagina). Aqui vira uma faixa real no
// cabecalho, varias linhas onduladas empilhadas com opacidade decrescente,
// nao uma linha unica quase invisivel.
function faixaTopografica(altura, corLinha) {
  let paths = '';
  const alturas = [0.30, 0.45, 0.58, 0.70, 0.80, 0.88];
  const opacidades = [0.55, 0.42, 0.32, 0.24, 0.16, 0.10];
  for (let i = 0; i < alturas.length; i++) {
