    if (v.km_percorrido) kmFilial += parseFloat(v.km_percorrido);
    const grupoDW = v.grupo_veiculo || 'Outros';
    if (!catMap[grupoDW]) catMap[grupoDW] = { grupo_veiculo: grupoDW, veiculos: 0, km: 0, litros: 0, gasto: 0 };
