  const kmFilialAnt = parseFloat(d.total_km_ant || 0);
  const custoKmCombFilial = parseFloat(d.custo_km_comb_medido || 0) > 0 ? parseFloat(d.custo_km_comb_medido) : (kmFilial > 0 ? gastoComb / kmFilial : null);

