  const totalVeicFil = frota.length;
  let perfil = 'Mista (Operação Combinada)';
  if (totalVeicFil > 0) {
    if (cTruckBitruck / totalVeicFil >= 0.5) perfil = 'Caminhões (Truck / Bitruck)';
    else if (cToco34 / totalVeicFil >= 0.5) perfil = 'Caminhões (Toco / 3/4)';
    else if (cCaminhoes / totalVeicFil >= 0.5) perfil = 'Caminhões (Pesados / Médios)';
    else if (cVansPesado / totalVeicFil >= 0.4) perfil = 'Vans e Furgões (Pesados)';
    else if (cLeveMedio / totalVeicFil >= 0.5) perfil = 'Leve / Médio (Pickups e Carros)';
