      postosMap[pKey] = { posto: p.posto || 'Posto', cidade: p.cidade || 'N/D', uf: p.uf || 'N/D',
        combustivel: p.combustivel || 'Diesel S-10', litros: 0, gasto: 0, preco_anp: parseFloat(p.preco_anp || 6.22) };
    }
    postosMap[pKey].litros += parseFloat(p.total_litros || 0);
    postosMap[pKey].gasto += parseFloat(p.total_gasto || 0);
  }

  filiaisList.push({ nome: nomeFilial, perfil, veic, km: kmFilial, litros, gastoComb, pm,
    desvioAnp: desvioAnpFilial, custoKmComb: custoKmCombFilial });
}

// Frota cadastrada total: HARDCODED no original (nao vem do banco).
// Preservado -- ver comentario no topo do arquivo.
const totalFrotaCadastrada = 530;
const taxaAderenciaFrota = ((sumVeiculos / totalFrotaCadastrada) * 100).toFixed(1);

const precoMedioGeral = sumLitros > 0 ? (sumGastoComb / sumLitros) : 0;
const precoMedioAntGeral = sumLitrosAnt > 0 ? (sumGastoCombAnt / sumLitrosAnt) : 0;
const custoKmCombGeral = sumKm > 0 ? (sumGastoComb / sumKm) : null;
const custoKmCombAntGeral = sumKmAnt > 0 ? (sumGastoCombAnt / sumKmAnt) : null;

let totalGastoCombPonderado = 0, totalGastoAnpEsperado = 0;
for (const f of filiaisList) {
  totalGastoCombPonderado += f.gastoComb;
  const gastoAnpFil = f.gastoComb / (1 + (f.desvioAnp / 100));
  totalGastoAnpEsperado += (isNaN(gastoAnpFil) || gastoAnpFil <= 0) ? f.gastoComb : gastoAnpFil;
}
const desvioAnpGeral = totalGastoAnpEsperado > 0 ? (((totalGastoCombPonderado - totalGastoAnpEsperado) / totalGastoAnpEsperado) * 100) : -1.8;
const sinalGeral = desvioAnpGeral > 0 ? '+' : '';
const desvioGeralStr = sinalGeral + fmtDec(desvioAnpGeral, 1) + '%';

const kpiCustoKmComb = calcVar(custoKmCombGeral, custoKmCombAntGeral, (v) => 'R$ ' + fmtDec(v, 2) + '/km');
const kpiPrecoDiesel = calcVar(precoMedioGeral, precoMedioAntGeral, (v) => 'R$ ' + fmtDec(v, 2) + '/L');
const kpiKm = calcVar(sumKm, sumKmAnt, (v) => numBr(v, 0) + ' km');
const kpiGastoComb = calcVar(sumGastoComb, sumGastoCombAnt, moeda);
const kpiLitros = calcVar(sumLitros, sumLitrosAnt, (v) => numBr(v, 0) + ' L');

// Linha de TOTAL -- mesmo pedido do node por filial (24/08/2026): sempre
// fechar com uma soma, mesmo repetindo numero que ja apareceu em cima.
const linhaTotal = (celulas) =>
  '<tr>' + celulas.map((c, i) =>
    '<td style="padding:10px 16px;text-align:' + (i === 0 ? 'left' : 'right') + ';font-weight:800;'
    + 'color:' + GRAFITE + ';font-size:12px;background:' + FUNDO + ';border-top:1.6px solid ' + VERDE + ';'
    + 'font-variant-numeric:tabular-nums;font-family:' + F_CORPO + '">' + c + '</td>'
  ).join('') + '</tr>';

// --- Categorias DW: veiculos + consumo medio (km/L), empresa toda ---------
const ordemDW = ['Bitruck', 'Truck', 'Toco', '3/4', 'Pesado', 'Médio', 'Leve', 'Moto', 'Outros'];
let rowsCategorias = '';
for (const grupo of ordemDW) {
  const cat = catMap[grupo];
  if (!cat || cat.veiculos === 0) continue;
  const cKm = cat.km > 0 ? cat.gasto / cat.km : null;
  const kmL = cat.litros > 0 ? cat.km / cat.litros : null;
  rowsCategorias += '<tr>'
    + '<td style="padding:9px 16px;font-weight:700;color:' + GRAFITE + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-family:' + F_CORPO + '">' + cat.grupo_veiculo + '</td>'
    + '<td style="padding:9px 16px;text-align:center;color:' + CINZA + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + cat.veiculos + '</td>'
    + '<td style="padding:9px 16px;text-align:right;color:' + CINZA + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + (cat.km > 0 ? numBr(cat.km, 0) + ' km' : 'N/D') + '</td>'
    + '<td style="padding:9px 16px;text-align:right;color:' + CINZA + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + numBr(cat.litros, 0) + ' L</td>'
    + '<td style="padding:9px 16px;text-align:right;font-weight:700;color:' + GRAFITE + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + moeda(cat.gasto) + '</td>'
    + '<td style="padding:9px 16px;text-align:right;font-weight:700;color:' + VERDE_ESC + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + (cKm !== null ? 'R$ ' + fmtDec(cKm, 2) + '/km' : 'N/D') + '</td>'
    + '<td style="padding:9px 16px;text-align:right;color:' + GRAFITE + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + (kmL !== null ? fmtDec(kmL, 2) + ' km/L' : 'N/D') + '</td>'
    + '</tr>';
}
if (rowsCategorias) {
  const kmLGeral = sumLitros > 0 ? (sumKm / sumLitros) : null;
  rowsCategorias += linhaTotal([
    'TOTAL', String(sumVeiculos), numBr(sumKm, 0) + ' km', numBr(sumLitros, 0) + ' L', moeda(sumGastoComb),
    custoKmCombGeral ? 'R$ ' + fmtDec(custoKmCombGeral, 2) + '/km' : 'N/D',
    kmLGeral !== null ? fmtDec(kmLGeral, 2) + ' km/L' : 'N/D',
  ]);
}

// --- Ranking por filial (sem colunas de pedagio) ----------------------------
let rowsFiliais = '';
for (const f of filiaisList.sort((a, b) => b.gastoComb - a.gastoComb)) {
  const desvioCor = f.desvioAnp <= 0 ? VERDE_ESC : (f.desvioAnp > 2 ? ALERTA : ATENCAO);
  rowsFiliais += '<tr>'
    + '<td style="padding:9px 16px;font-weight:700;color:' + GRAFITE + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-family:' + F_CORPO + '">' + f.nome + '</td>'
    + '<td style="padding:9px 16px;color:' + CINZA + ';font-size:11.5px;border-bottom:1px solid ' + LINHA + '">' + f.perfil + '</td>'
    + '<td style="padding:9px 16px;text-align:center;color:' + CINZA + ';font-size:12px;border-bottom:1px solid ' + LINHA + '">' + f.veic + '</td>'
    + '<td style="padding:9px 16px;text-align:right;color:' + CINZA + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + (f.km > 0 ? numBr(f.km, 0) : 'N/D') + '</td>'
    + '<td style="padding:9px 16px;text-align:right;color:' + CINZA + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + numBr(f.litros, 0) + '</td>'
    + '<td style="padding:9px 16px;text-align:right;font-weight:700;color:' + GRAFITE + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + moeda(f.gastoComb) + '</td>'
    + '<td style="padding:9px 16px;text-align:right;font-weight:700;color:' + VERDE_ESC + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + (f.custoKmComb !== null ? 'R$ ' + fmtDec(f.custoKmComb, 2) : 'N/D') + '</td>'
    + '<td style="padding:9px 16px;text-align:center;font-weight:700;color:' + desvioCor + ';font-size:11.5px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + (f.desvioAnp > 0 ? '+' : '') + fmtDec(f.desvioAnp, 1) + '%</td>'
    + '</tr>';
}
if (rowsFiliais) {
  rowsFiliais += linhaTotal([
    'TOTAL GERAL', '', String(sumVeiculos), numBr(sumKm, 0), numBr(sumLitros, 0), moeda(sumGastoComb),
    custoKmCombGeral ? 'R$ ' + fmtDec(custoKmCombGeral, 2) : 'N/D', desvioGeralStr,
  ]);
}

// --- Top 10 veiculos, frota toda -------------------------------------------
// Novo 24/08/2026 -- ver opiniao no resumo da conversa: o consolidado antes
// so tinha filial/categoria/posto, nada por placa. Um veiculo problematico
// numa filial pequena podia passar batido no ranking por filial; aqui ele
// aparece se estiver entre os 10 maiores gastos da empresa toda.
const topVeiculosGeral = todosVeiculos.slice().sort((a, b) => b.valor_total - a.valor_total).slice(0, 10);
let rowsTopVeiculos = '';
for (const v of topVeiculosGeral) {
  const custoKmV = v.km_percorrido > 0 ? (v.valor_total / v.km_percorrido) : null;
  rowsTopVeiculos += '<tr>'
    + '<td style="padding:9px 16px;font-weight:700;color:' + GRAFITE + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-family:' + F_CORPO + '">' + v.placa + '</td>'
    + '<td style="padding:9px 16px;color:' + CINZA + ';font-size:12px;border-bottom:1px solid ' + LINHA + '">' + v.filial + '</td>'
    + '<td style="padding:9px 16px;color:' + CINZA + ';font-size:12px;border-bottom:1px solid ' + LINHA + '">' + v.grupo_veiculo + '</td>'
    + '<td style="padding:9px 16px;color:' + CINZA + ';font-size:12px;border-bottom:1px solid ' + LINHA + '">' + v.combustivel + '</td>'
    + '<td style="padding:9px 16px;text-align:right;color:' + CINZA + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + numBr(v.total_litros, 0) + ' L</td>'
    + '<td style="padding:9px 16px;text-align:right;font-weight:700;color:' + GRAFITE + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + moeda(v.valor_total) + '</td>'
    + '<td style="padding:9px 16px;text-align:right;color:' + CINZA + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + (custoKmV != null ? moeda(custoKmV) + '/km' : 'N/D') + '</td>'
    + '</tr>';
}

// --- Top postos, rede inteira ------------------------------------------------
const topPostos = Object.values(postosMap).map(p => {
  const pm = p.litros > 0 ? (p.gasto / p.litros) : 0;
  const desvio = p.preco_anp > 0 ? (((pm - p.preco_anp) / p.preco_anp) * 100) : 0;
  return { ...p, preco_pago: pm, desvio_pct: desvio };
}).sort((a, b) => b.gasto - a.gasto).slice(0, 8);

let rowsTopPostos = '';
for (const p of topPostos) {
  const desvioStr = (p.desvio_pct > 0 ? '+' : '') + fmtDec(p.desvio_pct, 1) + '%';
  const desvioCor = p.desvio_pct <= 0 ? VERDE_ESC : ALERTA;
  rowsTopPostos += '<tr>'
    + '<td style="padding:9px 16px;font-weight:700;color:' + GRAFITE + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-family:' + F_CORPO + '">' + p.posto + '</td>'
    + '<td style="padding:9px 16px;color:' + CINZA + ';font-size:12px;border-bottom:1px solid ' + LINHA + '">' + cleanCityUf(p.cidade, p.uf) + '</td>'
    + '<td style="padding:9px 16px;color:' + CINZA + ';font-size:12px;border-bottom:1px solid ' + LINHA + '">' + p.combustivel + '</td>'
    + '<td style="padding:9px 16px;text-align:right;color:' + CINZA + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + numBr(p.litros, 0) + ' L</td>'
    + '<td style="padding:9px 16px;text-align:right;font-weight:700;color:' + GRAFITE + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + moeda(p.gasto) + '</td>'
    + '<td style="padding:9px 16px;text-align:right;color:' + GRAFITE + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + moeda(p.preco_pago) + '/L</td>'
    + '<td style="padding:9px 16px;text-align:center;font-weight:700;color:' + desvioCor + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + desvioStr + '</td>'
    + '</tr>';
}

// Destinatarios do consolidado: agora vem do banco (torre.email_gritsch_config,
// chaves consolidado_destinatarios/consolidado_cc), MESMA fonte e mesmas
// chaves que a telemetria ja usa -- antes era uma lista fixa no codigo, e
// por isso o padrao de envio divergia entre os dois relatorios. Corrigido
// 24/08/2026. O valor e igual em toda linha (veio de CROSS JOIN na SQL),
// entao basta ler do primeiro item.
const primeiro = items[0] ? items[0].json : {};
const destinatariosDb = primeiro.consolidado_destinatarios_db || 'jefferson@gritsch.com.br';
const ccDb = primeiro.consolidado_cc_db
  || 'sandro@gritsch.com.br,torredecontrole@gritsch.com.br,flavio@gritsch.com.br,fabio.pepplow@gritsch.com.br';
const emailFinal = modoProducao ? destinatariosDb : emailTeste;
const ccFinal = modoProducao ? ccDb : '';
// Tarja visual de teste removida a pedido do usuario (24/08/2026) -- o e-mail
// deve ficar visualmente identico ao que vai pra producao. O modo_producao
// continua controlando SO o destinatario (emailFinal/ccFinal), nao mais
// a aparencia do corpo do e-mail.
const faixaTeste = '';

// --- Componentes de layout (identicos ao node por filial) ------------------
const th = (txt, align) =>
  '<th style="padding:10px 16px;text-align:' + (align || 'left') + ';font-size:11px;font-weight:700;'
  + 'text-transform:uppercase;letter-spacing:0.04em;color:' + BRANCO + ';background:' + VERDE + ';'
  + 'font-family:' + F_CORPO + '">' + txt + '</th>';

const faixaSecao = (titulo) =>
  '<tr><td style="padding:26px 32px 0"><table width="100%" cellpadding="0" cellspacing="0"><tr>'
  + '<td style="background:' + VERDE_ESC + ';border-radius:6px 6px 0 0;padding:10px 18px;'
  + 'font-size:13px;font-weight:700;color:' + BRANCO + ';text-transform:uppercase;letter-spacing:0.03em;'
  + 'font-family:' + F_CORPO + '">' + titulo + '</td></tr></table></td></tr>';

const linhaKpi = (indicador, kpi) =>
  '<tr>'
  + '<td style="padding:11px 16px;font-size:13px;color:' + GRAFITE + ';font-weight:600;border-bottom:1px solid ' + LINHA + ';font-family:' + F_CORPO + '">' + indicador + '</td>'
  + '<td style="padding:11px 16px;text-align:right;font-size:13px;font-weight:700;color:' + GRAFITE + ';border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums;font-family:' + F_CORPO + '">' + kpi.atualStr + '</td>'
  + '<td style="padding:11px 16px;text-align:right;font-size:13px;color:' + CINZA + ';border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums;font-family:' + F_CORPO + '">' + kpi.antStr + '</td>'
  + '<td style="padding:11px 16px;text-align:right;font-size:13px;color:' + CINZA + ';border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums;font-family:' + F_CORPO + '">' + kpi.pctStr + '</td>'
  + '</tr>';

function faixaTopografica(altura, corLinha) {
  let paths = '';
  const alturas = [0.30, 0.45, 0.58, 0.70, 0.80, 0.88];
  const opacidades = [0.55, 0.42, 0.32, 0.24, 0.16, 0.10];
  for (let i = 0; i < alturas.length; i++) {
    const y = Math.round(altura * alturas[i]);
    const amp = 10 - i;
    paths += '<path d="M-10 ' + y + ' Q 90 ' + (y - amp) + ' 190 ' + y + ' T 390 ' + y
      + ' T 590 ' + y + ' T 790 ' + y + '" fill="none" stroke="' + corLinha + '" '
      + 'stroke-opacity="' + opacidades[i] + '" stroke-width="1.6"/>';
  }
  return 'data:image/svg+xml;base64,' + Buffer.from(
    '<svg xmlns="http://www.w3.org/2000/svg" width="820" height="' + altura + '" preserveAspectRatio="none">' + paths + '</svg>'
  ).toString('base64');
}
const contornoTopo = faixaTopografica(72, VERDE);

// --- Documento --------------------------------------------------------------
const html = '<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8">'
+ '<meta name="viewport" content="width=device-width,initial-scale=1.0">'
+ '<link href="https://fonts.googleapis.com/css2?family=Manrope:wght@600;700;800&family=IBM+Plex+Sans:wght@400;500;600;700&display=swap" rel="stylesheet">'
+ '</head><body style="margin:0;padding:0;background:' + FUNDO + ';font-family:' + F_CORPO + '">'

+ '<table width="100%" cellpadding="0" cellspacing="0" style="background:' + FUNDO + ';padding:28px 0">'
+ '<tr><td align="center">'
+ '<table width="820" cellpadding="0" cellspacing="0" style="max-width:820px;width:100%;'
+ 'background:' + BRANCO + ';border:1px solid ' + LINHA + ';border-radius:10px">'

+ faixaTeste

+ '<tr><td style="background:' + FUNDO + ';border-radius:10px 10px 0 0;padding:0">'
+ '<img src="' + contornoTopo + '" width="820" height="72" style="display:block;width:100%;height:72px" alt="">'
+ '</td></tr>'
+ '<tr><td style="padding:20px 32px 18px">'
+ '<table width="100%" cellpadding="0" cellspacing="0"><tr>'
+ '<td valign="middle">'
// Logo oficial completa: icone + wordmark numa imagem so, sem caixa em
// volta -- pedido do usuario 24/08/2026, usando o SVG oficial deles.
+ '<img src="cid:logo_truckpag" height="28" style="display:block;height:28px;width:auto" alt="TruckPag">'
+ '<div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.08em;color:' + CINZA + ';margin-top:12px;font-family:' + F_CORPO + '">Torre de Controle · Combustível · visão consolidada</div>'
+ '<div style="font-size:21px;font-weight:800;color:' + GRAFITE + ';margin-top:3px;font-family:' + F_DISPLAY + '">Diretoria · todas as filiais</div>'
+ '</td>'
+ '<td valign="middle" align="right">'
+ '<div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.08em;color:' + CINZA + ';font-family:' + F_CORPO + '">Fechamento</div>'
+ '<div style="font-size:13px;color:' + GRAFITE + ';margin-top:6px;font-family:' + F_CORPO + '">' + dataRef + '</div>'
+ '<div style="font-size:11px;color:' + CINZA + ';margin-top:4px;font-family:' + F_CORPO + '">Aderência da frota: ' + taxaAderenciaFrota + '%</div>'
+ '</td>'
+ '</tr></table></td></tr>'
+ '<tr><td style="border-bottom:1px solid ' + LINHA + '"></td></tr>'

+ '<tr><td style="padding:22px 32px 0">'
+ '<table width="100%" cellpadding="0" cellspacing="0" style="border:1px solid ' + LINHA + ';border-radius:8px;overflow:hidden">'
+ '<tr>' + th('Indicador corporativo') + th('Atual', 'right') + th('Semana anterior', 'right') + th('Variação', 'right') + '</tr>'
+ linhaKpi('Custo por km · combustível', kpiCustoKmComb)
+ linhaKpi('Preço médio pago por litro (vs. ANP ' + desvioGeralStr + ')', kpiPrecoDiesel)
+ linhaKpi('Km total rodado', kpiKm)
+ linhaKpi('Gasto total com combustível', kpiGastoComb)
+ linhaKpi('Volume abastecido (litros)', kpiLitros)
+ '</table></td></tr>'

+ faixaSecao('Veículos abastecidos por categoria')
+ '<tr><td style="padding:0 32px"><table width="100%" cellpadding="0" cellspacing="0" style="border:1px solid ' + LINHA + ';border-top:none;border-radius:0 0 6px 6px">'
+ '<tr>' + th('Categoria') + th('Veíc.', 'center') + th('Km rodado', 'right') + th('Litros', 'right') + th('Gasto total', 'right') + th('Custo/km', 'right') + th('Consumo médio', 'right') + '</tr>'
+ rowsCategorias + '</table></td></tr>'

+ faixaSecao('Ranking por filial')
+ '<tr><td style="padding:0 32px"><table width="100%" cellpadding="0" cellspacing="0" style="border:1px solid ' + LINHA + ';border-top:none;border-radius:0 0 6px 6px">'
+ '<tr>' + th('Filial / CD') + th('Perfil frota') + th('Veíc.', 'center') + th('Km', 'right') + th('Litros', 'right') + th('Gasto', 'right') + th('Custo/km', 'right') + th('vs. ANP', 'center') + '</tr>'
+ rowsFiliais + '</table></td></tr>'

+ (rowsTopVeiculos ? (
  faixaSecao('Top 10 veículos · frota toda')
  + '<tr><td style="padding:0 32px"><table width="100%" cellpadding="0" cellspacing="0" style="border:1px solid ' + LINHA + ';border-top:none;border-radius:0 0 6px 6px">'
  + '<tr>' + th('Placa') + th('Filial') + th('Categoria') + th('Combustível') + th('Litros', 'right') + th('Gasto', 'right') + th('Custo/km', 'right') + '</tr>'
  + rowsTopVeiculos + '</table></td></tr>'
) : '')

+ faixaSecao('Postos parceiros · Top 8 · rede inteira')
+ '<tr><td style="padding:0 32px"><table width="100%" cellpadding="0" cellspacing="0" style="border:1px solid ' + LINHA + ';border-top:none;border-radius:0 0 6px 6px">'
+ '<tr>' + th('Posto parceiro') + th('Cidade / UF') + th('Combustível') + th('Volume', 'right') + th('Total gasto', 'right') + th('Preço pago', 'right') + th('vs. ANP', 'center') + '</tr>'
+ rowsTopPostos + '</table></td></tr>'

+ '<tr><td style="padding:24px 32px;background:' + AZUL_GRITSCH + ';border-radius:0 0 10px 10px">'
+ '<table width="100%" cellpadding="0" cellspacing="0"><tr>'
+ '<td valign="middle"><img src="' + GRITSCH_LOGO_BRANCA + '" width="110" style="display:block;width:110px;height:auto" alt="Gritsch"></td>'
+ '<td valign="middle" align="right" style="font-size:11px;color:' + BRANCO + ';line-height:1.7;font-family:' + F_CORPO + '">'
+ 'Relatório automático da Torre de Controle · semanal<br>'
+ 'Dados fornecidos pela TruckPag<br>'
+ 'torredecontrole@gritsch.com.br'
+ '</td></tr></table></td></tr>'

+ '</table></td></tr></table></body></html>';

return [{
  json: {
    htmlEmail: html,
    emailFinal,
    ccFinal,
